const inputJson = {
    "personalization": [
        "*Personalization*\n1. Opportunity: Highlighting William Bruner's journey from humble beginnings with Enjoyable Entertainment to founding NEC and growing it into an 8,000-square-foot warehouse operation.  \nSupporting Evidence: William Bruner started with catering and DJ experience, founded Enjoyable Entertainment in 2014, and has since expanded NEC under his leadership to include significant warehouse and staffing capabilities.  \n\n2. Opportunity: Complimenting William Bruner's focus on operational excellence and balanced team culture.  \nSupporting Evidence: His leadership emphasizes sustainable work motivation for staff and maintaining strong client relationships while balancing ambition with well-being."
    ],
    "pain_points_solutions": [
        "*Pain Points & Solutions*\n1. Pain Point: Managing client relationships and site inspections efficiently while handling daily operations.  \nSupporting Evidence: William Bruner is heavily involved in daily operations, site inspections, and client relationships, which can be time-consuming.  \nOffer: AI-powered CRM automation to streamline client follow-ups and site inspection scheduling, reducing manual workload.  \n\n2. Pain Point: Scaling operations and logistics as the company grows.  \nSupporting Evidence: NEC has expanded to an 8,000-square-foot warehouse with increased equipment and staffing needs.  \nOffer: AI-driven inventory and logistics management system to optimize warehouse operations, track equipment, and automate scheduling for trucking and staffing."
    ]
};

// Object to hold the final, structured output
const structuredOutput = {
    personalization_items: [],
    pain_point_items: []
};

/**
 * Helper function to extract and structure the data points
 * from the free-form text blocks based on keywords.
 * @param {string} type - The category (e.g., 'personalization' or 'pain_points_solutions').
 * @param {string} textBlock - The text containing the structured data.
 * @param {Array} targetArray - The array to push the structured objects into.
 */
function parseTextBlock(type, textBlock, targetArray) {
    // Split the block into individual points based on the leading number (e.g., "1. ")
    // We slice(1) to remove the introductory header (e.g., "*Personalization*\n")
    const sections = textBlock.split(/\n\d\. /).slice(1);

    sections.forEach((section, index) => {
        const item = {
            id: index + 1,
            // These will be dynamically populated based on the type
        };

        // --- Personalization Logic ---
        if (type === 'personalization') {
            item.focus = 'Opportunity'; // Renaming 'title' to 'focus' for clarity
            const titleMatch = section.match(/Opportunity:\s*([^]+?)\s*Supporting Evidence:/);
            const evidenceMatch = section.match(/Supporting Evidence:\s*([^]+)/);

            if (titleMatch) {
                item.opportunity = titleMatch[1].trim();
            }
            if (evidenceMatch) {
                item.evidence = evidenceMatch[1].trim();
            }

        // --- Pain Point Logic ---
        } else if (type === 'pain_points_solutions') {
            item.focus = 'Pain Point'; // Renaming 'title' to 'focus' for clarity
            const painPointMatch = section.match(/Pain Point:\s*([^]+?)\s*Supporting Evidence:/);
            const evidenceMatch = section.match(/Supporting Evidence:\s*([^]+?)\s*Offer:/);
            const offerMatch = section.match(/Offer:\s*([^]+)/);

            if (painPointMatch) {
                item.pain_point = painPointMatch[1].trim();
            }
            if (evidenceMatch) {
                item.evidence = evidenceMatch[1].trim();
            }
            if (offerMatch) {
                // The offer aligns perfectly with your OLPOY services!
                item.offer = offerMatch[1].trim();
            }
        }

        // Push the structured item to the target array
        targetArray.push(item);
    });
}

// Process the Personalization array
if (inputJson.personalization && inputJson.personalization.length > 0) {
    parseTextBlock('personalization', inputJson.personalization[0], structuredOutput.personalization_items);
}

// Process the Pain Points & Solutions array
if (inputJson.pain_points_solutions && inputJson.pain_points_solutions.length > 0) {
    parseTextBlock('pain_points_solutions', inputJson.pain_points_solutions[0], structuredOutput.pain_point_items);
}

// The Code node must return an array of items. Since you want all data in one object, 
// we wrap the structuredOutput object in an array.
return [{ json: structuredOutput }];
